import React, { useEffect, useState } from 'react';
import { useTranslation } from "react-i18next";
import GitHubIcon from '@material-ui/icons/GitHub'
import LinkedInIcon from '@material-ui/icons/LinkedIn'
import { about } from '../../portfolio'
import './About.css'
import pdf from "./CV_David_Sharma_DE.pdf"
import Type from "./Type"
const About = () => {
  const { i18n, t } = useTranslation();

  const { name, role, description, resume, social } = about
  const [pdfUrl, setPdfUrl] = useState('');

  useEffect(() => {
    const loadPdf = async () => {
      let pdf;
      if (i18n.language === 'de') {
        pdf = await import('./CV_David_Sharma_DE.pdf');
      } else {
        pdf = await import('./CV_David_Sharma_EN.pdf');
      }
      setPdfUrl(pdf.default);
    };

    loadPdf();
  }, [i18n.language]);
  // i18n.changeLanguage('en');

  return (
    <div className='about center'>
      {name && (
        <h1>
          {name}
        </h1>
      )}

      {role && <h2 className='about__role'> <Type/></h2>}
      <p className='about__desc'>{t("description")}</p>

    


      <div className='about__contact center'>
        {resume && (
          <a href={pdfUrl} target="_blank" rel="noopener noreferrer">
            <span type='button' className='btn btn--outline'>
            {t("resume")}
            </span>
          </a>
        )}

        {social && (
          <>
            {social.github && (
              <a
                href={social.github}
                aria-label='github'
                className='link link--icon'
              >
                <GitHubIcon />
              </a>
            )}

            {social.linkedin && (
              <a
                href={social.linkedin}
                aria-label='linkedin'
                className='link link--icon'
              >
                <LinkedInIcon />
              </a>
            )}
          </>
        )}
      </div>
    </div>
  )
}

export default About
