import uniqid from 'uniqid'
import GitHubIcon from '@material-ui/icons/GitHub'
import LaunchIcon from '@material-ui/icons/Launch'
import './BlogpostContainer.css'
import { useTranslation } from 'react-i18next';

const BlogpostContainer = ({ blogpost }) => {


  const { i18n, t } = useTranslation();

  return (
  <div className='project'>
    <h3>{t(blogpost.name)}</h3>

    <p className='project__description'>{t(blogpost.description)}</p>
    {blogpost.stack && (
      <ul className='project__stack'>
        {blogpost.stack.map((item) => (
          <li key={uniqid()} className='project__stack-item'>
            {item}
          </li>
        ))}
      </ul>
    )}

    {blogpost.sourceCode && (
      <a
        href={blogpost.sourceCode}
        aria-label='source code'
        className='link link--icon'
      >
        <GitHubIcon />
      </a>
    )}

    {blogpost.livePreview && (
      <a
        href={blogpost.livePreview}
        aria-label='live preview'
        className='link link--icon'
      >
        <LaunchIcon />
      </a>
    )}
  </div>
  )
    }
export default BlogpostContainer
